import{_ as e,o as l,c as d,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const M=JSON.parse('{"title":"CQM 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"D003_术语表.md","filePath":"D003_术语表.md"}'),i={name:"D003_术语表.md"};function n(s,t,r,f,x,y){return l(),d("div",null,[...t[0]||(t[0]=[a('<div><h1 id="cqm-术语表" tabindex="-1">CQM 术语表 <a class="header-anchor" href="#cqm-术语表" aria-label="Permalink to &quot;CQM 术语表&quot;">​</a></h1><blockquote><p>本表汇总 CQM 理论的全局术语与符号标准，供自动化比对与人工审校使用。 权威源：<code>README.md</code> 符号约定与数值表 &gt; 各概念权威定义处 &gt; <code>.workbuddy/审校/00_修订基准与准则.md</code> §2。 本表不新增任何术语，仅汇总既有标准。</p></blockquote><hr><h2 id="一、核心符号-不得改名、不得改变数值" tabindex="-1">一、核心符号（不得改名、不得改变数值） <a class="header-anchor" href="#一、核心符号-不得改名、不得改变数值" aria-label="Permalink to &quot;一、核心符号（不得改名、不得改变数值）&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">标准写法</th><th style="text-align:left;">数值/定义</th><th style="text-align:left;">权威处</th></tr></thead><tbody><tr><td style="text-align:left;">相变量子</td><td style="text-align:left;">$☯$（英文语境 $\\mathscr{C}$）</td><td style="text-align:left;">$☯=\\frac{d}{ds}\\ln\\xi(s)\\big|_{s=1}\\approx0.02309570897$</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td></tr><tr><td style="text-align:left;">第一耦级</td><td style="text-align:left;">$\\mathfrak{c}_1$</td><td style="text-align:left;">$200.04045483$（$=1/4+\\gamma_1^2$）</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">Mathieu 临界</td><td style="text-align:left;">$\\lambda_c$</td><td style="text-align:left;">$1.316022911$（$\\lambda_{\\min}(q_c)=2q_c$ 唯一根，$\\lambda_c=4q_c$）</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">Dynkin 指数比</td><td style="text-align:left;">$I$</td><td style="text-align:left;">$T(\\mathbf{24})/T(\\mathbf{8})=5/3$</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">谱修正</td><td style="text-align:left;">$\\kappa$</td><td style="text-align:left;">$(31+☯)/30$</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">时空同步前沿速度</td><td style="text-align:left;">$c$</td><td style="text-align:left;">不承担量纲转换</td><td style="text-align:left;">全库统一</td></tr><tr><td style="text-align:left;">禁闭映射常数</td><td style="text-align:left;">$K_L$</td><td style="text-align:left;">换算比值，非算符</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">转换常数族</td><td style="text-align:left;">$K_L,K_M,K_Q,K_\\Theta,K_N,K_J$</td><td style="text-align:left;">$K_M=G_N^{-1}$</td><td style="text-align:left;">集成理论</td></tr><tr><td style="text-align:left;">固有时流速</td><td style="text-align:left;">$v_\\tau$</td><td style="text-align:left;">$v_\\tau\\equiv d\\tau/dt$</td><td style="text-align:left;">FG 纤维丛理论</td></tr><tr><td style="text-align:left;">固有时流速共轭动量</td><td style="text-align:left;">$p_u$</td><td style="text-align:left;">——</td><td style="text-align:left;">FG 纤维丛理论</td></tr><tr><td style="text-align:left;">基本自守量纲</td><td style="text-align:left;">$[G_{\\max}(f)]$</td><td style="text-align:left;">极大关系群的同构类（唯一名；曾用名「基础量纲」「基础自守量纲」已废止）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5</td></tr><tr><td style="text-align:left;">量纲群</td><td style="text-align:left;">量纲群</td><td style="text-align:left;">唯一名（无别名）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.4.7</td></tr><tr><td style="text-align:left;">自守量纲</td><td style="text-align:left;">自守量纲</td><td style="text-align:left;">上位类：基本＋子（有自守形式对应）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5.13</td></tr><tr><td style="text-align:left;">子自守量纲</td><td style="text-align:left;">子自守量纲</td><td style="text-align:left;">极大关系群的子群 $[G\']$（$G\'<G_{\\max}$）定义的种类＝量纲内分化</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5.13</td></tr><tr><td style="text-align:left;">派生量纲</td><td style="text-align:left;">派生量纲</td><td style="text-align:left;">无自守形式对应的人为定义计量层量纲（物质的量；≠ SI 导出量纲）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5.13</td></tr><tr><td style="text-align:left;">属性锚点</td><td style="text-align:left;">属性锚点</td><td style="text-align:left;">$GL(n)$ 的矩阵元素 $g_{ij}$（属性先在侧的基点；≠ 自守链的锚点 §7.3）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5.13</td></tr><tr><td style="text-align:left;">潜在-显现化</td><td style="text-align:left;">潜在-显现化</td><td style="text-align:left;">「潜在-显现」指<strong>属性</strong>的两态：先在为潜在，经关系而显现（实例属性、自守形式、量纲）；潜在-显现化＝属性由潜在态向显现态转化的全过程，沿三环节展开：关系分化→实例化→具体化</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §6.5.13</td></tr></tbody></table><h2 id="二、牛顿引力常数" tabindex="-1">二、牛顿引力常数 <a class="header-anchor" href="#二、牛顿引力常数" aria-label="Permalink to &quot;二、牛顿引力常数&quot;">​</a></h2><p>$$G_N=\\frac{\\hbar c}{m_p^2}\\,I\\,\\lambda_c\\,☯^2\\,\\mathfrak{c}_1\\,\\exp\\!\\left(-\\frac{2}{☯}\\right)\\,(1+\\kappa ☯)$$</p><table tabindex="0"><thead><tr><th style="text-align:left;">量</th><th style="text-align:left;">值</th></tr></thead><tbody><tr><td style="text-align:left;">理论值</td><td style="text-align:left;">$6.708811657\\times10^{-39}$ GeV$^{-2}$</td></tr><tr><td style="text-align:left;">SI 值</td><td style="text-align:left;">$6.6742810045\\times10^{-11}$ m$^3$kg$^{-1}$s$^{-2}$</td></tr><tr><td style="text-align:left;">偏差</td><td style="text-align:left;">$-3$ ppm</td></tr><tr><td style="text-align:left;">质子质量</td><td style="text-align:left;">$m_p=0.9382720882$ GeV</td></tr></tbody></table><blockquote><p>凡出现 $G_N$ 数值或偏差之处，必须带限定语：&quot;构造后验数字校验，待独立复现&quot;。</p></blockquote><h2 id="三、群与代数写法" tabindex="-1">三、群与代数写法 <a class="header-anchor" href="#三、群与代数写法" aria-label="Permalink to &quot;三、群与代数写法&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">对象</th><th style="text-align:left;">标准写法</th><th style="text-align:left;">变体（须改）</th></tr></thead><tbody><tr><td style="text-align:left;">具体 n</td><td style="text-align:left;">$\\mathrm{GL}(5)$、$\\mathrm{SU}(5)$、$\\mathrm{GL}(2)$</td><td style="text-align:left;"><code>GL_5</code>、<code>SU_5</code>、<code>GL5</code>、<code>SU5</code></td></tr><tr><td style="text-align:left;">一般 n</td><td style="text-align:left;">$\\mathrm{GL}(n)$、$\\mathrm{SU}(n)$</td><td style="text-align:left;"><code>GLn</code>、<code>SUn</code></td></tr><tr><td style="text-align:left;">嘉当矩阵</td><td style="text-align:left;">$A_4$（数学环境）</td><td style="text-align:left;">纯文本 <code>A4</code></td></tr><tr><td style="text-align:left;">李代数</td><td style="text-align:left;">$\\mathfrak{su}(5)$</td><td style="text-align:left;">$\\hat{\\mathfrak{su}}_5$</td></tr><tr><td style="text-align:left;">本征群</td><td style="text-align:left;">$\\{SU(2)_k\\}_{k=1}^{4}$（全紧致，单因子）</td><td style="text-align:left;">$\\{SU(2)_k\\}_{k=1}^4$、$SU(2)_{orb}\\times SU(2)_{spin}$</td></tr><tr><td style="text-align:left;">商群</td><td style="text-align:left;">$U(1)//\\mathbb{Z}_n$</td><td style="text-align:left;">$Z_n$</td></tr></tbody></table><h2 id="四、中文译名标准" tabindex="-1">四、中文译名标准 <a class="header-anchor" href="#四、中文译名标准" aria-label="Permalink to &quot;四、中文译名标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">标准写法</th><th style="text-align:left;">须改的变体</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">时空同步前沿速度</td><td style="text-align:left;">时空前沿同步速度</td><td style="text-align:left;">词频 34:9</td></tr><tr><td style="text-align:left;">晶胞量子振荡</td><td style="text-align:left;">晶格量子振荡</td><td style="text-align:left;">词频 76:11</td></tr><tr><td style="text-align:left;">p 进（中文行文带空格）</td><td style="text-align:left;">p进（无空格）</td><td style="text-align:left;">专名保留 p-adic</td></tr><tr><td style="text-align:left;">Adele（专名首字母大写）</td><td style="text-align:left;">adele</td><td style="text-align:left;">形容词 adelic</td></tr><tr><td style="text-align:left;">万尼尔函数／万尼尔插值</td><td style="text-align:left;">外尔函数／外尔插值</td><td style="text-align:left;">仅指 Wannier 处</td></tr><tr><td style="text-align:left;">贝里曲率</td><td style="text-align:left;">Berry 曲率（中文行文）</td><td style="text-align:left;">首现可括注 Berry curvature</td></tr><tr><td style="text-align:left;">因果网络同步理论（CNST）</td><td style="text-align:left;">裸缩写 CNST</td><td style="text-align:left;">首现处展开</td></tr><tr><td style="text-align:left;">Sierra-CQM 耦谱定理</td><td style="text-align:left;">Sierra-CQM 定理</td><td style="text-align:left;">用 README 口径</td></tr><tr><td style="text-align:left;">结构群叠加态</td><td style="text-align:left;">叠加群／叠加的超导群</td><td style="text-align:left;">首现处说明同义</td></tr><tr><td style="text-align:left;">同步算符</td><td style="text-align:left;">三词随意混用</td><td style="text-align:left;">首现处写明&quot;同步算符=紧化算符的层级实现&quot;</td></tr><tr><td style="text-align:left;">引力因果限制场（FG）</td><td style="text-align:left;">引力因果场</td><td style="text-align:left;">主名带&quot;限制&quot;，余作别名括注</td></tr><tr><td style="text-align:left;">超导同步算符</td><td style="text-align:left;">$\\hat{\\mathcal{S}}_{\\text{super}}$</td><td style="text-align:left;">旧符号 $\\hat{\\mathcal{S}}_{\\text{SC}}$ 须改</td></tr></tbody></table><h2 id="五、人名区间-统一-en-dash-–" tabindex="-1">五、人名区间（统一 en dash <code>–</code>） <a class="header-anchor" href="#五、人名区间-统一-en-dash-–" aria-label="Permalink to &quot;五、人名区间（统一 en dash `–`）&quot;">​</a></h2><p>Hilbert–Pólya、Berry–Keating、Fröhlich–Morchio–Strocchi、Fradkin–Shenker、Kibble–Zurek、Sekino &amp; Susskind</p><h2 id="六、箭头约定" tabindex="-1">六、箭头约定 <a class="header-anchor" href="#六、箭头约定" aria-label="Permalink to &quot;六、箭头约定&quot;">​</a></h2><ul><li><code>⇒</code> <strong>仅</strong>表示<strong>重组实现</strong>；一般演化、极限、映射一律用 <code>→</code>。</li><li>链条写法：$\\mathrm{GL}(5)$ ⇒ $\\mathrm{SU}(5)$（重组实现）。</li></ul><h2 id="七、不得擅自统一的登记项" tabindex="-1">七、不得擅自统一的登记项 <a class="header-anchor" href="#七、不得擅自统一的登记项" aria-label="Permalink to &quot;七、不得擅自统一的登记项&quot;">​</a></h2><p>以下记号/数值在库中分属不同主用文档，<strong>无法判定为同一量的异写</strong>，保持原样并登记：</p><table tabindex="0"><thead><tr><th style="text-align:left;">记号/争议</th><th style="text-align:left;">分布</th><th style="text-align:left;">处置</th></tr></thead><tbody><tr><td style="text-align:left;">$\\Delta\\delta_v$ 与 $\\Delta\\delta_0$</td><td style="text-align:left;">专题与扩展、核心理论、集成理论、统一方法论</td><td style="text-align:left;">保持原样，逐处登记</td></tr><tr><td style="text-align:left;">$K_{\\rm eff}$ 幂指数、$\\theta_D$ 指数多套取值</td><td style="text-align:left;">专题与扩展 §11</td><td style="text-align:left;">保持原样，登记</td></tr><tr><td style="text-align:left;">同位素趋势方向</td><td style="text-align:left;">专题与扩展</td><td style="text-align:left;">保持原样，登记</td></tr><tr><td style="text-align:left;">缺口 G5 归属</td><td style="text-align:left;">集成理论 / 黎曼猜想 / 待推1</td><td style="text-align:left;">按 README 与集成理论统一</td></tr></tbody></table><hr><p><em>依据：<code>00_修订基准与准则.md</code> §2 · 生成时间：2026-10-05</em></p></div>',1)])])}const C=e(i,[["render",n]]);export{M as __pageData,C as default};
